/* Muted web copy of Minoo's approved Four Butterflies studio clip. */
(() => {
 const video = document.getElementById('custom-studio-video');
 const button = document.getElementById('custom-studio-toggle');
 if (!video || !button) return;
 const motion = window.matchMedia('(prefers-reduced-motion: reduce)');
 video.poster = 'data:image/webp;base64,';
 const bytes = Uint8Array.from(atob(''), c => c.charCodeAt(0));
 video.src = URL.createObjectURL(new Blob([bytes], {type:'video/mp4'}));
 video.muted = true;
 const syncLabel = () => {button.textContent = video.paused ? 'Play studio motion' : 'Pause studio motion';};
 button.hidden = false;
 video.addEventListener('play', syncLabel);
 video.addEventListener('pause', syncLabel);
 video.addEventListener('error', () => {button.hidden = true;});
 button.addEventListener('click', () => {
   if (video.paused) video.play().catch(syncLabel);
   else video.pause();
 });
 motion.addEventListener('change', e => {if(e.matches) video.pause();});
 if (!motion.matches) video.play().catch(syncLabel);
})();